"use client";

import Link from "next/link";
import { CreditCard } from "lucide-react";
import { BillingControls } from "@/components/billing-controls";
import { DateTime } from "@/components/date-time";
import type { ClientBillingStatus } from "@/lib/billing/status";
import { PRICE_CONFIG } from "@/lib/pricing";
import { SettingsPanel } from "./SettingsPanel";
import { SubscriptionMenu } from "./SubscriptionMenu";

export function PlanSummary({ billing }: { billing: ClientBillingStatus }) {
  return (
    <BillingControls
      initialBilling={billing}
      advertisedPrice={PRICE_CONFIG.DEFAULT}
      renderContent={(c) => {
        const b = c.billing;
        return (
          <SettingsPanel
            id="plan"
            title="Plan and subscription"
            icon={CreditCard}
            description="Manage your subscription and review verified billing details."
          >
            <div className="grid gap-4 text-sm text-[var(--settings-muted)]">
              <p>
                Current plan:{" "}
                <strong className="text-[var(--settings-text)]">
                  {b?.plan === "PAID" ? "Premium" : "Free"}
                </strong>
                {b &&
                  ` · Subscription: ${b.status.toLowerCase().replaceAll("_", " ")}`}
              </p>
              {c.hasSubscription ? (
                <p>
                  Stored recurring amount before tax:{" "}
                  <strong className="text-[var(--settings-text)]">
                    {c.recurring}
                  </strong>
                  . Invoices show applicable tax.
                </p>
              ) : b &&
                b.status !== "NONE" &&
                (b.recurringAmountMinor !== null || b.recurringCurrency) ? (
                <details>
                  <summary className="min-h-11 cursor-pointer py-3 text-[var(--settings-purple)]">
                    Previous subscription
                  </summary>
                  <p>
                    Previous recurring amount before tax:{" "}
                    <strong>{c.recurring}</strong>. This is the stored amount
                    for your previous subscription. It does not renew.
                  </p>
                </details>
              ) : null}
              {b?.isSuspended && (
                <p className="text-[var(--settings-yellow)]">
                  Sending and Premium features are suspended. Suspension does
                  not cancel billing. You can still manage or cancel your
                  subscription.
                </p>
              )}
              {c.pending && (
                <p role="status">
                  Waiting for verified payment confirmation. Access updates
                  automatically after confirmation; this can take several
                  minutes.
                </p>
              )}
              {b?.cancellationPending && (
                <p role="status">
                  Cancellation requested. Waiting for confirmation; your
                  verified Premium period is retained.
                </p>
              )}
              {b?.cancelAtPeriodEnd && b.periodEnd && (
                <p>
                  Cancellation scheduled. Verified Premium access ends{" "}
                  <DateTime value={b.periodEnd} />.
                </p>
              )}
              {b?.status === "PAST_DUE" && b.gracePeriodEnd && (
                <p className="text-[var(--settings-yellow)]">
                  Renewal payment needs attention. The verified grace period
                  ends <DateTime value={b.gracePeriodEnd} />.
                </p>
              )}
              {b?.status === "ACTIVE" &&
                !b.cancelAtPeriodEnd &&
                b.periodEnd && (
                  <p>
                    Next monthly renewal: <DateTime value={b.periodEnd} />.
                    Verified Premium period ends at this time.
                  </p>
                )}
              {b && !b.configured && (
                <p>
                  Checkout is not configured yet. Subscription controls are
                  unavailable until configuration is restored; stored
                  subscription details remain visible.
                </p>
              )}
              {b?.configured && !b.checkoutEnabled && (
                <p>Checkout is currently disabled.</p>
              )}
              {b?.configured && b.isSuspended && (
                <p>
                  Upgrades are unavailable while suspended. Contact support
                  about account access.
                </p>
              )}
              {b?.configured && !b.hasCustomer && (
                <p>Manage is available after a billing account is created.</p>
              )}
              <div className="grid min-w-0 grid-cols-[44px_minmax(0,1fr)] items-center gap-3 border-t border-[var(--settings-border)] pt-4 sm:flex sm:flex-wrap">
                {b?.hasCustomer && (
                  <button
                    type="button"
                    className="secondary-button button-interaction col-span-2 min-h-11 w-full cursor-pointer rounded-full border border-[var(--settings-strong)] px-5 py-2.5 font-semibold text-[var(--settings-text)] sm:w-auto"
                    aria-busy={c.busy}
                    disabled={!c.canManage || c.busy}
                    onClick={() => void c.open("portal")}
                  >
                    {c.busy ? "Opening…" : "Manage subscription"}
                  </button>
                )}
                <SubscriptionMenu controls={c} />
                <Link
                  href="/usage"
                  className="ml-auto inline-flex min-h-11 min-w-0 items-center text-right text-[var(--settings-purple)] underline underline-offset-4"
                >
                  View usage and allowances
                </Link>
              </div>
              {c.lookupFailed && (
                <p role="alert" className="text-[var(--settings-yellow)]">
                  Subscription status lookup temporarily failed. Your last
                  verified status is retained. Try refreshing shortly.
                </p>
              )}
              {c.message && (
                <p
                  role="alert"
                  className={
                    c.message ===
                    "Cancellation requested. Waiting for confirmation."
                      ? "text-[var(--settings-muted)]"
                      : "text-[var(--status-error-text)]"
                  }
                >
                  {c.message}
                </p>
              )}
            </div>
          </SettingsPanel>
        );
      }}
    />
  );
}
